INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-HIST-004-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-004'), 3, 'Romanesque Architecture', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Period: c. 1000-1200 CE, Western Europe", "type": "fact"}, {"text": "Round arches — defining structural and decorative element", "type": "fact"}, {"text": "Thick masonry walls with small windows — fortress-like appearance", "type": "fact"}, {"text": "Barrel vaults and groin vaults over nave — stone replacing timber roofs", "type": "fact"}, {"text": "Latin cross plan: nave, transept, choir, apse, ambulatory, radiating chapels", "type": "fact"}, {"text": "Towers — twin west front towers and/or crossing tower", "type": "fact"}, {"text": "Durham Cathedral — first systematic use of ribbed groin vault (proto-Gothic)", "type": "fact"}, {"text": "Pisa Cathedral complex — cathedral, baptistery, campanile (Leaning Tower)", "type": "fact"}, {"text": "Cluny Abbey III — largest church in Christendom until St. Peter''s", "type": "fact"}, {"text": "Pilgrimage churches: Santiago de Compostela, St. Sernin (Toulouse)", "type": "fact"}, {"text": "Arcade, triforium, clerestory — three-level nave wall elevation", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-004-03'
