SELECT 'ALE-HIST-004-04', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-004'), 3, 'Gothic Architecture', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'analyze'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application'], '[{"text": "Pointed arch — distributes thrust more efficiently than round arch", "type": "fact"}, {"text": "Ribbed vault — skeleton of pointed arches with thin infill panels", "type": "fact"}, {"text": "Flying buttress — external arch transferring vault thrust to outer pier, allowing thin walls", "type": "fact"}, {"text": "Large stained glass windows — rose windows, lancet windows; walls of light", "type": "fact"}, {"text": "Verticality — soaring naves, pointed spires, emphasis on height and aspiration", "type": "concept"}, {"text": "Notre-Dame de Paris (1163-1345) — iconic French Gothic, flying buttresses, rose windows", "type": "fact"}, {"text": "Chartres Cathedral — High Gothic, complete stained glass program, labyrinth", "type": "fact"}, {"text": "Cologne Cathedral — largest Gothic cathedral in Northern Europe, twin spires 157m", "type": "fact"}, {"text": "Sainte-Chapelle, Paris — Rayonnant Gothic, walls almost entirely glass", "type": "fact"}, {"text": "Amiens Cathedral — tallest French Gothic nave (42.3m), High Gothic", "type": "fact"}, {"text": "Westminster Abbey — English Gothic, Perpendicular style fan vaulting", "type": "fact"}, {"text": "Milan Cathedral — Italian Gothic, marble, Flamboyant style", "type": "fact"}, {"text": "Gothic phases: Early (Lancet), High (Rayonnant), Late (Flamboyant/Perpendicular/Decorated)", "type": "concept"}, {"text": "Tracery — decorative stone framework in windows (plate tracery → bar tracery)", "type": "definition"}, {"text": "Fan vault — English Perpendicular specialty (King''s College Chapel, Cambridge)", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-004-04'
FROM public.disciplines d WHERE d.acronym = 'ALE'
