SELECT 'ALE-HIST-007-01', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-007'), 3, 'Indian Architecture', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Buddhist Architecture: Stupas — hemispherical dome over relic (Great Stupa at Sanchi, oldest extant stupa)", "type": "fact"}, {"text": "Stupa elements: anda (dome), harmika (square railing on top), chattra (umbrella/parasol), torana (gateway)", "type": "fact"}, {"text": "Rock-cut architecture: Ajanta Caves (Buddhist monasteries/paintings), Ellora Caves (Kailasa Temple, monolithic)", "type": "fact"}, {"text": "Hindu Temple — Nagara style (N. India, curvilinear shikhara tower): Kandariya Mahadeva, Khajuraho", "type": "fact"}, {"text": "Hindu Temple — Dravidian style (S. India, pyramidal vimana tower): Sri Ranganathaswamy, Meenakshi Amman, Brihadeeswarar", "type": "fact"}, {"text": "Gopuram — towering ornate gateway towers of Dravidian temples", "type": "definition"}, {"text": "Mughal Architecture: synthesis of Islamic, Persian, and Indian traditions", "type": "concept"}, {"text": "Taj Mahal (1632-53) — white marble, char bagh garden, onion dome, pietra dura inlay", "type": "fact"}, {"text": "Red Fort, Delhi — Mughal palace complex, red sandstone", "type": "fact"}, {"text": "Fatehpur Sikri — Akbar''s abandoned capital, Buland Darwaza (tallest gateway)", "type": "fact"}, {"text": "Vastu Shastra — ancient Indian architectural treatise (directional principles, five elements)", "type": "definition"}, {"text": "Jain temples — elaborate marble carving, Dilwara Temples at Mount Abu", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-007-01'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
