SELECT 'ALE-HIST-007-02', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-007'), 3, 'Chinese Architecture', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Timber frame structure — post-and-beam, non-load-bearing walls", "type": "fact"}, {"text": "Dougong (bracket sets) — interlocking timber brackets supporting eaves, signature Chinese element", "type": "definition"}, {"text": "Curved/upturned roof eaves — ceramic glazed tile roofing, ridge ornaments", "type": "fact"}, {"text": "Pagodas — multi-tiered towers (Buddhist); timber, brick, or stone", "type": "fact"}, {"text": "Forbidden City, Beijing (1406-20) — largest palace complex, 980 buildings, axial symmetry, 72 hectares", "type": "fact"}, {"text": "Temple of Heaven, Beijing — circular Hall of Prayer for Good Harvests, triple-gable roof", "type": "fact"}, {"text": "Great Wall of China — defensive fortification, various dynasties, c. 21,196 km total", "type": "fact"}, {"text": "Siheyuan — traditional courtyard house, inward-facing rooms, hierarchical layout", "type": "definition"}, {"text": "Feng Shui — geomantic principles for siting and orientation (wind-water harmony)", "type": "definition"}, {"text": "Axial symmetry and hierarchy — north-south axis, importance increases toward rear/center", "type": "concept"}, {"text": "Color symbolism: yellow (imperial), red (good fortune), green (growth)", "type": "fact"}, {"text": "Moon gates, spirit walls (yingbi), ornamental bridges", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-007-02'
FROM public.disciplines d WHERE d.acronym = 'ALE'
