SELECT 'ALE-HIST-007-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-007'), 3, 'Japanese Architecture', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Shinto shrines — Ise Grand Shrine (rebuilt every 20 years, shinmei-zukuri style), torii gates", "type": "fact"}, {"text": "Buddhist temples — Todai-ji (Nara, largest wooden building, Great Buddha Hall/Daibutsuden)", "type": "fact"}, {"text": "Horyuji Temple (607 CE) — oldest surviving wooden structure in the world", "type": "fact"}, {"text": "Tatami module — standardized floor mat (approx. 910×1820mm) as spatial unit", "type": "fact"}, {"text": "Shoji screens — translucent sliding paper panels; Fusuma — opaque sliding panels", "type": "fact"}, {"text": "Engawa — transitional veranda between interior and garden", "type": "definition"}, {"text": "Modularity and flexibility — rooms defined by sliding partitions, not fixed walls", "type": "concept"}, {"text": "Katsura Imperial Villa (1620s) — prototype of Japanese aesthetic, influenced modernists", "type": "fact"}, {"text": "Japanese garden types: karesansui (dry/zen rock garden), tsukiyama (hill garden), chaniwa (tea garden)", "type": "fact"}, {"text": "Tea house (chashitsu) — wabi-sabi aesthetic, humility, rustic simplicity", "type": "fact"}, {"text": "Castle architecture: Himeji Castle — ''White Heron Castle,'' defensive and aesthetic masterpiece", "type": "fact"}, {"text": "Post-and-beam timber construction, earthquake-resistant joinery (no nails)", "type": "fact"}, {"text": "Metabolism movement (1960s) — Kenzo Tange, Kisho Kurokawa; megastructures, capsule architecture", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-007-03'
