SELECT 'ALE-HIST-008-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-008'), 3, 'Early Modernists & Pioneers', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'analyze'::public.bloom_level_type, 3, ARRAY['mcq_recall','mcq_application'], '[{"text": "Frank Lloyd Wright — Organic Architecture; Prairie Houses (Robie House), Fallingwater (1935), Guggenheim Museum NY (1959)", "type": "fact"}, {"text": "Le Corbusier — Five Points of Architecture (pilotis, free plan, free façade, horizontal windows, roof garden)", "type": "fact"}, {"text": "Le Corbusier — Villa Savoye (1929), Unité d''Habitation (1947), Chapel of Ronchamp (1955), Chandigarh", "type": "fact"}, {"text": "Le Corbusier — ''Modulor'' proportional system based on human body and golden ratio", "type": "fact"}, {"text": "Ludwig Mies van der Rohe — ''Less is more''; Barcelona Pavilion (1929), Farnsworth House (1951), Seagram Building (1958)", "type": "fact"}, {"text": "Walter Gropius — Bauhaus School founder (Weimar 1919, Dessau 1925); Bauhaus Building, Dessau", "type": "fact"}, {"text": "Alvar Aalto — Finnish modernism, humanistic approach; Paimio Sanatorium, Villa Mairea, Finlandia Hall", "type": "fact"}, {"text": "Louis Kahn — ''served and servant spaces,'' monumental modern; Salk Institute, Kimbell Art Museum, National Assembly Bangladesh", "type": "fact"}, {"text": "Oscar Niemeyer — Brazilian modernism, free-form concrete; Brasília (with Lúcio Costa), Cathedral of Brasília", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-008-03'
FROM public.disciplines d WHERE d.acronym = 'ALE'
