SELECT 'ALE-HIST-008-04', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-008'), 3, 'Major Modern Movements', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'analyze'::public.bloom_level_type, 3, ARRAY['mcq_recall','mcq_application'], '[{"text": "Bauhaus (1919-1933) — Gropius, Meyer, Mies; unity of art/craft/technology; Dessau building as manifesto", "type": "fact"}, {"text": "International Style (1920s-1970s) — Philip Johnson/Hitchcock coined term (1932 MoMA exhibit); glass curtain wall, flat roofs, no ornament", "type": "fact"}, {"text": "De Stijl (1917-1931) — Mondrian, Rietveld; primary colors, orthogonal geometry; Rietveld Schröder House (1924)", "type": "fact"}, {"text": "Constructivism — Russian avant-garde, Tatlin''s Tower (Monument to Third International, 1920, unbuilt)", "type": "fact"}, {"text": "Expressionism — Erich Mendelsohn (Einstein Tower), Hans Scharoun (Berlin Philharmonic), emotional/sculptural form", "type": "fact"}, {"text": "Metabolism (Japan, 1960s) — Kenzo Tange, Kurokawa; megastructures, biological growth metaphor; Nakagin Capsule Tower", "type": "fact"}, {"text": "Organic Architecture — Wright''s principle: building as extension of nature, not imposed upon it", "type": "concept"}, {"text": "Futurism — Antonio Sant''Elia, ''Città Nuova'' (1914); speed, dynamism, technology worship", "type": "fact"}, {"text": "CIAM (Congrès Internationaux d''Architecture Moderne, 1928-1959) — Athens Charter (1933), functional city zoning", "type": "fact"}, {"text": "Team X — reaction against CIAM rigidity (Smithsons, Van Eyck, Candilis); human association patterns", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-008-04'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
