SELECT 'ALE-HIST-008-05', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-008'), 3, 'Brutalism & Late Modernism', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Brutalism (1950s-1970s) — béton brut (raw concrete), massive forms, honest materials, social housing", "type": "definition"}, {"text": "Le Corbusier''s Unité d''Habitation (1947-52) — proto-Brutalist, raw concrete, streets in the sky", "type": "fact"}, {"text": "Alison & Peter Smithson — Robin Hood Gardens, ''New Brutalism'' manifesto", "type": "fact"}, {"text": "Paul Rudolph — Yale Art & Architecture Building (now Rudolph Hall), heroic concrete", "type": "fact"}, {"text": "Tadao Ando — contemporary concrete master; Church of the Light, Water Temple, Pulitzer Arts Foundation", "type": "fact"}, {"text": "Late Modernism — continuation of modernist forms with high-tech materials (Renzo Piano, Richard Rogers, Norman Foster)", "type": "concept"}, {"text": "High-Tech Architecture: Centre Pompidou (Piano + Rogers, 1977), Lloyd''s Building (Rogers), Hong Kong Shanghai Bank (Foster)", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-008-05'
FROM public.disciplines d WHERE d.acronym = 'ALE'
