SELECT 'ALE-HIST-008-06', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-008'), 3, 'Postmodernism', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 3, ARRAY['mcq_recall','mcq_application'], '[{"text": "Postmodernism (1960s-1990s) — reaction against modernist austerity; irony, historical reference, ornament, color", "type": "definition"}, {"text": "Robert Venturi — ''Complexity and Contradiction in Architecture'' (1966), ''Less is a bore''; Vanna Venturi House", "type": "fact"}, {"text": "Charles Moore — Piazza d''Italia, New Orleans (1978), playful classical fragments", "type": "fact"}, {"text": "Michael Graves — Portland Building (1982), Team Disney Building; colorful, referential", "type": "fact"}, {"text": "Philip Johnson — AT&T Building (now 550 Madison), Chippendale pediment top", "type": "fact"}, {"text": "Aldo Rossi — ''The Architecture of the City'' (1966), typology and urban memory", "type": "fact"}, {"text": "Venturi, Scott Brown & Izenour — ''Learning from Las Vegas'' (1972); ''decorated shed'' vs. ''duck''", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-008-06'
FROM public.disciplines d WHERE d.acronym = 'ALE'
