SELECT 'ALE-HIST-008-07', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-008'), 3, 'Deconstructivism & Parametricism', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 3, ARRAY['mcq_recall'], '[{"text": "Deconstructivism — fragmentation, distortion, unpredictability; 1988 MoMA exhibition (Johnson/Wigley)", "type": "definition"}, {"text": "Frank Gehry — Guggenheim Museum Bilbao (1997, titanium), Walt Disney Concert Hall; ''Bilbao Effect''", "type": "fact"}, {"text": "Zaha Hadid — Vitra Fire Station, MAXXI Rome, Heydar Aliyev Center; first woman Pritzker (2004)", "type": "fact"}, {"text": "Daniel Libeskind — Jewish Museum Berlin (2001), angular voids and fractures", "type": "fact"}, {"text": "Rem Koolhaas — CCTV Headquarters Beijing, Seattle Central Library; OMA; ''Delirious New York''", "type": "fact"}, {"text": "Parametricism — Patrik Schumacher (term coined 2008), algorithmic/computational design, Zaha Hadid Architects", "type": "definition"}, {"text": "Digital fabrication and computational tools enabling complex geometries", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-hist-008-07'
FROM public.disciplines d WHERE d.acronym = 'ALE'
