SELECT 'ALE-HIST-008-08', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-008'), 3, 'Critical Regionalism & Sustainable Architecture', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Critical Regionalism — Kenneth Frampton (1983); modern techniques + local culture, climate, materials, topography", "type": "definition"}, {"text": "Geoffrey Bawa (Sri Lanka) — tropical modernism, Kandalama Hotel, Parliament of Sri Lanka", "type": "fact"}, {"text": "Hassan Fathy (Egypt) — ''Architecture for the Poor'' (1973), New Gourna village, mud brick, passive cooling", "type": "fact"}, {"text": "Glenn Murcutt (Australia) — ''touch the earth lightly,'' corrugated metal, climate-responsive; Pritzker 2002", "type": "fact"}, {"text": "Ken Yeang (Malaysia) — bioclimatic skyscrapers, Menara Mesiniaga, vertical landscaping", "type": "fact"}, {"text": "Sustainable/Green Architecture — LEED, passive design, net-zero energy, biomimicry, adaptive reuse", "type": "concept"}, {"text": "Diébédo Francis Kéré (Burkina Faso) — community-built, local materials, ventilation innovation; Pritzker 2022", "type": "fact"}, {"text": "Contextualism — buildings that respond to their urban/cultural context rather than being autonomous objects", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-hist-008-08'
FROM public.disciplines d WHERE d.acronym = 'ALE'
