SELECT 'ALE-HIST-008-09', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-008'), 3, 'Pritzker Prize Laureates & Contemporary Masters', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Pritzker Architecture Prize — established 1979 by Hyatt Foundation, ''Nobel of Architecture''", "type": "definition"}, {"text": "Philip Johnson (1979) — first laureate, Glass House, AT&T Building", "type": "fact"}, {"text": "I.M. Pei (1983) — Louvre Pyramid, National Gallery East Building, EDSA Shangri-La (Manila)", "type": "fact"}, {"text": "Tadao Ando (1995) — self-taught, concrete and light, Church of the Light", "type": "fact"}, {"text": "Renzo Piano (1998) — Centre Pompidou (with Rogers), The Shard (London), Kansai Airport", "type": "fact"}, {"text": "Norman Foster (1999) — High-Tech, 30 St Mary Axe (Gherkin), Reichstag dome, Hong Kong Airport", "type": "fact"}, {"text": "Rem Koolhaas (2000) — OMA, CCTV HQ Beijing, ''Delirious New York'', S,M,L,XL", "type": "fact"}, {"text": "Zaha Hadid (2004) — first woman laureate, parametric forms, Heydar Aliyev Center", "type": "fact"}, {"text": "Peter Zumthor (2009) — Therme Vals, atmospheric/phenomenological architecture", "type": "fact"}, {"text": "SANAA / Kazuyo Sejima + Ryue Nishizawa (2010) — minimal, transparent; 21st Century Museum Kanazawa", "type": "fact"}, {"text": "Wang Shu (2012) — Chinese, recycled materials, Ningbo History Museum", "type": "fact"}, {"text": "Shigeru Ban (2014) — humanitarian, paper tube structures, disaster relief shelters", "type": "fact"}, {"text": "Alejandro Aravena (2016) — social housing (half-a-good-house), ELEMENTAL, Chile", "type": "fact"}, {"text": "Balkrishna Doshi (2018) — Indian modernism, student of Le Corbusier, IIM Bangalore, Aranya Housing", "type": "fact"}, {"text": "Arata Isozaki (2019) — Japanese postmodernism, bridging East and West", "type": "fact"}, {"text": "Anne Lacaton & Jean-Philippe Vassal (2021) — ''never demolish,'' transformation over replacement", "type": "fact"}, {"text": "Diébédo Francis Kéré (2022) — Burkina Faso, community empowerment, local materials", "type": "fact"}, {"text": "David Chipperfield (2023) — restrained modernism, Neues Museum Berlin restoration", "type": "fact"}, {"text": "Riken Yamamoto (2024) — Japanese, community-oriented, interconnected living spaces", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-008-09'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();

-- ALE-HIST-009
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-HIST-009-01', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-009'), 3, 'African Architecture', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Great Zimbabwe (11th-15th c.) — Shona civilization, dry-stone walls (no mortar), Great Enclosure, conical tower", "type": "fact"}, {"text": "Great Mosque of Djenné, Mali — largest mud-brick (adobe) building in the world, annually replastered", "type": "fact"}, {"text": "Dogon cliff dwellings (Mali) — granaries and houses built into Bandiagara Escarpment", "type": "fact"}, {"text": "Lalibela rock-hewn churches, Ethiopia — 11 monolithic churches carved from bedrock (12th-13th c.)", "type": "fact"}, {"text": "Nubian pyramids, Meroë — smaller, steeper than Egyptian pyramids, Kingdom of Kush", "type": "fact"}, {"text": "Timbuktu — mud-brick mosques and madrasas, Sankore University, center of Islamic learning", "type": "fact"}, {"text": "Vernacular: round huts (tukul), thatched roofs, compound/kraal layouts, adaptation to climate zones", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-009-01'
FROM public.disciplines d WHERE d.acronym = 'ALE'
