SELECT 'ALE-HIST-009-02', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-009'), 3, 'Pre-Columbian Americas', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Mayan Architecture — stepped pyramids, corbelled arch (false vault); El Castillo at Chichén Itzá, Palenque, Tikal", "type": "fact"}, {"text": "Aztec Architecture — Tenochtitlan (Great Temple/Templo Mayor), twin-temple pyramid, chinampas (floating gardens)", "type": "fact"}, {"text": "Inca Architecture — precision-cut polygonal stone, no mortar; Machu Picchu, Sacsayhuamán, trapezoidal openings", "type": "fact"}, {"text": "Pueblo architecture — Taos Pueblo, adobe multi-story communal dwellings, American Southwest", "type": "fact"}, {"text": "Cahokia Mounds — largest pre-Columbian settlement north of Mexico, earthen platform mounds", "type": "fact"}, {"text": "Nazca Lines, Peru — massive geoglyphs, landscape-scale design", "type": "fact"}, {"text": "Easter Island (Rapa Nui) — Moai statues, ahu ceremonial platforms, volcanic tuff", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-009-02'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();

