SELECT 'ALE-HIST-010-01', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-010'), 3, 'Pre-Colonial & Vernacular Architecture', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Bahay Kubo (nipa hut) — indigenous stilt house, bamboo/nipa/cogon, elevated floor, ventilation, modular", "type": "fact"}, {"text": "Torogan — Maranao royal house (Lanao), elaborate panolong (wing-like beams), okir carvings", "type": "fact"}, {"text": "Ifugao Rice Terraces — 2,000-year-old engineered landscape, Banaue, UNESCO World Heritage", "type": "fact"}, {"text": "Bale/Balay — general term for house; regional variations across ethnic groups", "type": "fact"}, {"text": "Ivatan stone houses (Batanes) — typhoon-resistant, limestone/coral walls, cogon roof", "type": "fact"}, {"text": "Badjao (sea nomads) — stilt houses over water, boat-dwelling traditions", "type": "fact"}, {"text": "Indigenous materials: bamboo, nipa palm, rattan, timber, cogon grass, stone (limited)", "type": "fact"}, {"text": "Climate adaptation: elevated floor (flooding, ventilation, animals), steep roof (rain), open plan (airflow)", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-hist-010-01'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
