SELECT 'ALE-HIST-010-02', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-010'), 3, 'Spanish Colonial Architecture (1565-1898)', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application'], '[{"text": "Bahay na Bato — stone lower floor + wooden upper floor, synthesis of Spanish and Filipino building traditions", "type": "fact"}, {"text": "Intramuros — walled city of Manila (1571), defensive fortifications, cathedral, government buildings", "type": "fact"}, {"text": "Baroque Churches of the Philippines (UNESCO): San Agustin (Manila), Paoay, Santa Maria, Miag-ao", "type": "fact"}, {"text": "San Agustin Church, Manila (1607) — oldest stone church in the Philippines, Baroque", "type": "fact"}, {"text": "Paoay Church, Ilocos Norte — ''Earthquake Baroque,'' massive buttresses, coral stone", "type": "fact"}, {"text": "Miag-ao Church, Iloilo — Baroque-Romanesque, unique tropical relief façade (coconut, papaya motifs)", "type": "fact"}, {"text": "Earthquake Baroque — Philippine adaptation: massive buttresses, low profiles, thick walls for seismic resistance", "type": "definition"}, {"text": "Town plaza system — church, municipio (town hall), plaza, market — Spanish colonial urban pattern (Laws of the Indies)", "type": "concept"}, {"text": "Fort Santiago, Manila — citadel within Intramuros, defense against invasions", "type": "fact"}, {"text": "Vigan — UNESCO World Heritage city, best-preserved Spanish colonial town in Asia, ancestral houses", "type": "fact"}, {"text": "Materials: adobe (coral stone blocks), brick, timber, tisa (roof tiles), lime mortar with egg whites", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-010-02'
FROM public.disciplines d WHERE d.acronym = 'ALE'
