SELECT 'ALE-HIST-010-04', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-010'), 3, 'Post-War & Independence Era Architecture', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Post-WWII reconstruction: Manila devastated (second most destroyed city after Warsaw), rebuilding era", "type": "fact"}, {"text": "Marcos-era monumental architecture: Cultural Center of the Philippines (Leandro Locsin, 1969), PICC, Folk Arts Theater", "type": "fact"}, {"text": "Araneta Coliseum (1960) — largest indoor arena in Asia at the time, dome without interior columns", "type": "fact"}, {"text": "Philippine International Convention Center (Locsin, 1976) — floating appearance, brutalist concrete", "type": "fact"}, {"text": "UP Diliman campus — post-war master plan, modernist campus buildings", "type": "fact"}, {"text": "Shift from colonial historicism to international modernism, concrete as dominant material", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-hist-010-04'
FROM public.disciplines d WHERE d.acronym = 'ALE'
