SELECT 'ALE-HIST-010-05', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-HIST-010'), 3, 'Pillars of Philippine Architecture', 'History of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Juan Nakpil (1899-1986) — National Artist for Architecture (1973), ''Dean of Filipino Architects,'' Rizal Theater, Quezon Institute", "type": "fact"}, {"text": "Pablo Antonio (1901-1975) — National Artist for Architecture (1976), Manila Polo Club, Ideal Theater, Far Eastern University buildings; Art Deco-Modern", "type": "fact"}, {"text": "Carlos Arguelles (1918-1996) — Manila Hilton (now Waterfront Manila Pavilion), Philbanking Building, modern commercial", "type": "fact"}, {"text": "Leandro Locsin (1928-1994) — National Artist for Architecture (1990), CCP, PICC, Istana Nurul Iman (Brunei Palace); ''floating volume'' aesthetic", "type": "fact"}, {"text": "Francisco ''Bobby'' Mañosa (1931-2020) — neo-vernacular/Filipino architecture, Coconut Palace (1981), San Miguel Corporation HQ", "type": "fact"}, {"text": "Ildefonso Santos Jr. (1929-2014) — National Artist for Landscape Architecture (2006), Philippine landscape design, Luneta Park redevelopment", "type": "fact"}, {"text": "José María Zaragoza — Church architect, EDSA Shrine, San Antonio de Padua Church", "type": "fact"}, {"text": "Felino Palafox Jr. — contemporary urban planner, Clark Green City masterplan, ''green urbanism''", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-hist-010-05'
FROM public.disciplines d WHERE d.acronym = 'ALE'
