UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Definition of history and history of architecture", "type": "definition"}, {"text": "Historic style of architecture — what defines a ''style''", "type": "definition"}, {"text": "Origin of architecture — shelter, ritual, social organization", "type": "concept"}, {"text": "Factors affecting style: Environmental (climate, geography, materials)", "type": "concept"}, {"text": "Factors affecting style: Historical (political events, conquests, trade)", "type": "concept"}, {"text": "Factors affecting style: Socio-Cultural (religion, customs, economy)", "type": "concept"}, {"text": "Framework for analyzing any historic style: period/extent, factors, characteristics, contributions, notable examples", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-001-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Menhirs — upright standing stones (e.g., Carnac, Brittany)", "type": "fact"}, {"text": "Dolmens — stone table tombs (capstone on uprights)", "type": "fact"}, {"text": "Cromlechs — circular stone arrangements (Stonehenge, Avebury)", "type": "fact"}, {"text": "Tumuli — burial mounds over chambers", "type": "fact"}, {"text": "Passage Graves (Newgrange, Ireland — c. 3200 BCE)", "type": "fact"}, {"text": "Henges — circular earthwork enclosures", "type": "fact"}, {"text": "Göbekli Tepe (c. 9500 BCE) — oldest known monumental structure, Neolithic, SE Turkey", "type": "fact"}, {"text": "Çatalhöyük (c. 7500 BCE) — earliest known proto-urban settlement, no streets, rooftop access", "type": "fact"}, {"text": "Post-and-lintel (trabeated) as the earliest structural system", "type": "concept"}, {"text": "Construction materials: earth, timber, stone — locally sourced", "type": "fact"}, {"text": "Jericho — oldest known continuously inhabited city; earliest defensive walls (c. 8000 BCE)", "type": "fact"}, {"text": "Skara Brae, Orkney — Neolithic village (c. 3180 BCE), stone furniture", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-001-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Mastabas — flat-roofed rectangular tombs, earliest royal burials", "type": "fact"}, {"text": "Step Pyramid of Djoser at Saqqara (c. 2650 BCE) — designed by Imhotep, first monumental stone building", "type": "fact"}, {"text": "Pyramids of Giza — Khufu (Great Pyramid, 146m), Khafre, Menkaure", "type": "fact"}, {"text": "Great Sphinx of Giza — limestone, lion body with pharaoh head", "type": "fact"}, {"text": "Temple of Karnak — largest religious complex ever built, Hypostyle Hall (134 columns)", "type": "fact"}, {"text": "Temple of Luxor — connected to Karnak by Avenue of Sphinxes", "type": "fact"}, {"text": "Mortuary Temple of Hatshepsut at Deir el-Bahari — terraced, colonnaded, Senenmut architect", "type": "fact"}, {"text": "Abu Simbel — rock-cut temple of Ramesses II, relocated by UNESCO (1968)", "type": "fact"}, {"text": "Pylons — monumental entrance gateways with battered (sloping) walls", "type": "fact"}, {"text": "Obelisks — tapered monolithic shafts with pyramidion cap", "type": "fact"}, {"text": "Cavetto Cornice — concave molding, signature Egyptian decorative element", "type": "fact"}, {"text": "Column capitals: Papyriform (papyrus bud/bell), Lotiform (lotus), Palmiform (palm leaf), Hathor-headed", "type": "fact"}, {"text": "Hypostyle Halls — dense forest of columns supporting stone lintels, clerestory lighting", "type": "fact"}, {"text": "Battered walls — inward-sloping exterior walls for stability and visual mass", "type": "fact"}, {"text": "Dromos — ceremonial processional avenue, often sphinx-lined", "type": "fact"}, {"text": "Post-and-lintel (trabeated) construction — no true arches", "type": "concept"}, {"text": "Materials: limestone, sandstone, granite; mudbrick for domestic", "type": "fact"}, {"text": "Orientation: temples aligned to cardinal directions, emphasis on east-west axis (sun path)", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-002-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Ziggurats — stepped temple platforms (White Temple of Uruk, Ziggurat of Ur, Chogha Zanbil)", "type": "fact"}, {"text": "Hanging Gardens of Babylon — one of Seven Wonders, attributed to Nebuchadnezzar II", "type": "fact"}, {"text": "Ishtar Gate of Babylon — glazed blue brick, processional way, relief animals", "type": "fact"}, {"text": "Palaces: Palace of Sargon at Khorsabad, Palace at Nineveh, Palace of Mari", "type": "fact"}, {"text": "City Walls of Jericho — among earliest defensive fortifications", "type": "fact"}, {"text": "Sumerian, Babylonian, Assyrian civilizations — successive Mesopotamian empires", "type": "fact"}, {"text": "Materials: sun-dried mud brick (adobe), kiln-fired brick, bitumen mortar", "type": "fact"}, {"text": "Structural innovation: true arch and barrel vault developed here", "type": "concept"}, {"text": "Lamassu — human-headed winged bull/lion guardian figures at palace gates", "type": "fact"}, {"text": "Glazed brick decoration and relief sculpture as surface treatment", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-002-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Persepolis — ceremonial capital of Achaemenid Empire, Apadana audience hall", "type": "fact"}, {"text": "Apadana — large hypostyle audience hall with double bull capitals", "type": "fact"}, {"text": "Pasargadae — capital of Cyrus the Great, Tomb of Cyrus", "type": "fact"}, {"text": "Iwan — vaulted hall open on one end, became standard in later Islamic architecture", "type": "fact"}, {"text": "Double bull capitals (protomes) — unique Achaemenid column detail", "type": "fact"}, {"text": "Synthesis style: combined Egyptian, Greek, Mesopotamian elements under Persian program", "type": "concept"}, {"text": "Materials: stone platform bases, mud brick walls, timber columns, glazed brick decoration", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-002-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Harappa and Mohenjo-Daro — twin cities of Indus Valley (c. 2600-1900 BCE)", "type": "fact"}, {"text": "Grid-plan cities — earliest known urban planning with orthogonal streets", "type": "fact"}, {"text": "Great Bath of Mohenjo-Daro — earliest known public water tank/pool", "type": "fact"}, {"text": "Advanced drainage and sewage systems — covered drains beneath streets", "type": "fact"}, {"text": "Standardized fired bricks — uniform ratio (4:2:1), used across entire civilization", "type": "fact"}, {"text": "Citadel and lower town — two-part city organization, elevated public/religious precinct", "type": "fact"}, {"text": "Granaries — large centralized food storage structures", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-002-04';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Doric Order — fluted column, no base, triglyphs/metopes frieze (Parthenon, Hephaesteum, Temple of Poseidon at Paestum)", "type": "fact"}, {"text": "Ionic Order — volute capital, continuous frieze, slender proportions (Erechtheion, Temple of Artemis at Ephesus, Temple of Athena Nike)", "type": "fact"}, {"text": "Corinthian Order — acanthus leaf capital (Choragic Monument of Lysicrates, Temple of Olympian Zeus)", "type": "fact"}, {"text": "Parthenon (447-432 BCE) — Ictinus & Callicrates, architects; Phidias, sculptor; Doric peripteral octastyle", "type": "fact"}, {"text": "Erechtheion — Porch of the Caryatids (female figure columns), Ionic, Acropolis", "type": "fact"}, {"text": "Acropolis of Athens — sacred hilltop complex: Parthenon, Erechtheion, Propylaea, Temple of Athena Nike", "type": "fact"}, {"text": "Propylaea — monumental gateway to the Acropolis", "type": "fact"}, {"text": "Theater of Epidaurus — finest acoustics, semicircular, seating 14,000", "type": "fact"}, {"text": "Agora — civic/commercial center of the Greek polis", "type": "definition"}, {"text": "Stoa — covered colonnade walkway used for public gathering (Stoa of Attalos)", "type": "definition"}, {"text": "Optical refinements: entasis (column swelling), stylobate curvature, corner column thickening, column inclination", "type": "concept"}, {"text": "Golden Ratio (1:1.618) / Golden Section — proportional system used in Greek temples", "type": "concept"}, {"text": "Temple plans: in antis, prostyle, amphiprostyle, peripteral, dipteral, pseudodipteral, tholos (circular)", "type": "fact"}, {"text": "Post-and-lintel (trabeated) construction — Greeks did not use arches", "type": "concept"}, {"text": "Materials: marble (Pentelic for Parthenon), limestone, timber roof framing", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-003-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Hellenistic Period (323-31 BCE) — post-Alexander expansion, grander scale, more dramatic emotion", "type": "definition"}, {"text": "Altar of Zeus at Pergamon (c. 180 BCE) — monumental frieze depicting Gigantomachy, Hellenistic Baroque", "type": "fact"}, {"text": "Pharos (Lighthouse) of Alexandria — one of Seven Wonders, c. 100m, three tiers (square, octagonal, cylindrical)", "type": "fact"}, {"text": "Library of Alexandria — largest ancient library, part of Ptolemaic Mouseion", "type": "fact"}, {"text": "Mausoleum at Halicarnassus — one of Seven Wonders, Ionic colonnade on massive podium", "type": "fact"}, {"text": "Shift from religious to secular civic buildings: libraries, gymnasia, theaters, market halls", "type": "concept"}, {"text": "Urban planning: Hippodamian grid plan (Hippodamus of Miletus)", "type": "concept"}, {"text": "Increased use of Corinthian order and mixed orders", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-003-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "True Arch — semicircular voussoir arch, Roman structural innovation", "type": "fact"}, {"text": "Barrel Vault — continuous semicircular vault (extended arch)", "type": "fact"}, {"text": "Groin Vault (cross vault) — intersection of two barrel vaults at right angles", "type": "fact"}, {"text": "Dome — hemispherical vault, perfected by Romans", "type": "fact"}, {"text": "Pantheon (c. 125 CE) — 43.3m unreinforced concrete dome, 8.2m oculus, coffered interior; by Apollodorus of Damascus (attributed)", "type": "fact"}, {"text": "Opus Caementicium — Roman concrete (volcanic ash/pozzolana + lime + aggregate)", "type": "fact"}, {"text": "Colosseum (Flavian Amphitheatre) — 50,000 capacity, superimposed orders (Doric-Ionic-Corinthian-Composite), velarium", "type": "fact"}, {"text": "Thermae — monumental public baths (Baths of Caracalla, Baths of Diocletian)", "type": "fact"}, {"text": "Roman Basilica — rectangular hall for law courts and commerce, became model for early Christian churches", "type": "fact"}, {"text": "Aqueducts — gravity-fed water supply (Pont du Gard, Aqua Claudia, Segovia)", "type": "fact"}, {"text": "Triumphal Arches — commemorative freestanding arches (Arch of Titus, Arch of Constantine)", "type": "fact"}, {"text": "Insulae — multi-story apartment blocks for urban housing, up to 6-8 stories", "type": "fact"}, {"text": "Domus — single-family Roman house: atrium, impluvium, compluvium, peristyle, tablinum", "type": "fact"}, {"text": "Roman Forums — civic centers (Forum Romanum, Forum of Trajan)", "type": "fact"}, {"text": "Composite Order and Tuscan Order — Roman additions to Greek orders", "type": "fact"}, {"text": "Roman roads, bridges, and engineering infrastructure", "type": "fact"}, {"text": "Vitruvius — ''De Architectura'' (Ten Books on Architecture): firmitas, utilitas, venustas", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-003-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Basilica plan adapted from Roman civic basilica: nave, side aisles, apse, narthex, atrium", "type": "fact"}, {"text": "Old St. Peter''s Basilica, Rome (c. 320 CE) — prototype basilican church, timber roof", "type": "fact"}, {"text": "Santa Sabina, Rome — classic Early Christian basilica, clerestory windows, Corinthian columns", "type": "fact"}, {"text": "Santa Maria Maggiore, Rome — one of four papal basilicas", "type": "fact"}, {"text": "Centralized plan churches: Santa Costanza (circular, mausoleum), San Vitale (octagonal)", "type": "fact"}, {"text": "Catacombs — underground burial chambers, early Christian worship spaces", "type": "fact"}, {"text": "Timber truss roof — not vaulted; simple post-and-lintel structure", "type": "concept"}, {"text": "Emphasis on interior decoration (mosaics, frescoes) over exterior ornamentation", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-004-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Hagia Sophia, Constantinople (532-537 CE) — Anthemius of Tralles & Isidorus of Miletus; 31m dome on pendentives", "type": "fact"}, {"text": "Pendentive — concave triangular spandrel transitioning square plan to circular dome", "type": "definition"}, {"text": "Squinch — arch/niche across corner, alternative to pendentive for dome transition", "type": "definition"}, {"text": "Greek cross plan — equal-arm cross, typical Byzantine church layout", "type": "fact"}, {"text": "Mosaic decoration — gold-ground tesserae, iconic imagery, interior surfaces", "type": "fact"}, {"text": "San Vitale, Ravenna — octagonal plan, mosaics of Justinian and Theodora", "type": "fact"}, {"text": "St. Mark''s Basilica, Venice — Greek cross plan, five domes, Byzantine-Romanesque fusion", "type": "fact"}, {"text": "Iconostasis — icon screen separating nave from sanctuary in Eastern churches", "type": "definition"}, {"text": "Materials: brick and mortar construction with marble and mosaic cladding", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-004-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Revival of classical Greek and Roman forms, orders, and proportional systems", "type": "concept"}, {"text": "Filippo Brunelleschi — Dome of Florence Cathedral (Santa Maria del Fiore, 1420-36), double-shell dome, herringbone brick", "type": "fact"}, {"text": "Brunelleschi — Ospedale degli Innocenti, Pazzi Chapel — rational classical arcades", "type": "fact"}, {"text": "Leon Battista Alberti — ''De Re Aedificatoria'' (1452), Palazzo Rucellai (superimposed orders), Sant''Andrea Mantua", "type": "fact"}, {"text": "Donato Bramante — Tempietto, Rome (1502, circular Doric peripteral); original St. Peter''s plan", "type": "fact"}, {"text": "Michelangelo — St. Peter''s Basilica dome (redesign), Laurentian Library, Capitoline Hill", "type": "fact"}, {"text": "Andrea Palladio — ''Four Books of Architecture'' (1570), Villa Rotonda, San Giorgio Maggiore; Palladian style", "type": "fact"}, {"text": "Palazzo type: rusticated base, piano nobile, cornice; e.g., Palazzo Medici-Riccardi (Michelozzo), Palazzo Farnese", "type": "fact"}, {"text": "Perspective — Brunelleschi''s discovery of linear perspective, architecture as geometrical art", "type": "concept"}, {"text": "Centralized plan ideal — circle and square as perfect forms (Leonardo, Bramante)", "type": "concept"}, {"text": "High Renaissance → Mannerism (Giulio Romano — Palazzo del Tè, deliberate rule-breaking)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-005-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Baroque (c. 1600-1750) — drama, movement, grandeur, emotional impact, Counter-Reformation expression", "type": "definition"}, {"text": "Gian Lorenzo Bernini — St. Peter''s Baldacchino, St. Peter''s Square colonnades, Sant''Andrea al Quirinale", "type": "fact"}, {"text": "Francesco Borromini — San Carlo alle Quattro Fontane (undulating façade), Sant''Ivo della Sapienza", "type": "fact"}, {"text": "Palace of Versailles (Louis Le Vau, Jules Hardouin-Mansart) — Hall of Mirrors, axial garden layout", "type": "fact"}, {"text": "St. Paul''s Cathedral, London (Sir Christopher Wren) — English Baroque, dome on drum", "type": "fact"}, {"text": "Rococo (c. 1720-1780) — lighter, more playful, pastel, organic ornament; primarily interiors", "type": "definition"}, {"text": "Rococo examples: Amalienburg Pavilion (Munich), Wieskirche (Bavaria), Queluz Palace (Portugal)", "type": "fact"}, {"text": "Characteristics: curved forms, oval plans, trompe l''oeil ceilings, theatrical lighting, integration of sculpture", "type": "concept"}, {"text": "Churrigueresque — exuberant Spanish Baroque (important for Philippine colonial churches)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-005-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Neoclassicism (c. 1750-1850) — reaction against Baroque/Rococo excess; return to Greek/Roman purity", "type": "definition"}, {"text": "Influenced by excavations at Pompeii/Herculaneum (1738+) and Winckelmann''s writings", "type": "fact"}, {"text": "Jacques-Germain Soufflot — Panthéon, Paris (1758-90), Greek cross plan with dome", "type": "fact"}, {"text": "Karl Friedrich Schinkel — Altes Museum, Berlin; Prussian Neoclassicism", "type": "fact"}, {"text": "Thomas Jefferson — Monticello, University of Virginia, US Capitol influence; Palladian-Neoclassical", "type": "fact"}, {"text": "British Museum (Robert Smirke) — Greek Revival, Ionic colonnade", "type": "fact"}, {"text": "US Capitol Building, Washington DC — Neoclassical dome, democratic ideals expressed in classical forms", "type": "fact"}, {"text": "Arc de Triomphe, Paris — Roman triumphal arch at grand scale", "type": "fact"}, {"text": "Characteristics: symmetry, classical orders used ''correctly,'' restrained ornament, archaeological accuracy", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-005-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Mosque (masjid) — essential components: qibla wall, mihrab (niche facing Mecca), minbar (pulpit), minaret", "type": "fact"}, {"text": "Hypostyle mosque plan — columned prayer hall (Great Mosque of Córdoba, 786+ CE)", "type": "fact"}, {"text": "Four-iwan mosque plan — central courtyard with vaulted halls on each side", "type": "fact"}, {"text": "Muqarnas — honeycomb/stalactite vaulting, decorative 3D corbelling", "type": "definition"}, {"text": "Arabesques — interlocking geometric and vegetal patterns (no figural representation)", "type": "definition"}, {"text": "Calligraphy — Quranic inscriptions as primary decorative element", "type": "fact"}, {"text": "Pointed arch — Islamic precedent predates Gothic use", "type": "fact"}, {"text": "Horseshoe arch — characteristic of Moorish/Western Islamic architecture", "type": "fact"}, {"text": "Dome — symbol of the heavens, used over mihrab and prayer halls", "type": "concept"}, {"text": "Courtyard (sahn) — central open space for gathering, ablution fountain", "type": "fact"}, {"text": "Mashrabiya — projecting wooden lattice screen window for privacy and ventilation", "type": "definition"}, {"text": "Geometric tilework (zellige) — mathematical precision, infinite pattern, horror vacui", "type": "fact"}, {"text": "Aniconism — prohibition of figurative imagery in religious spaces", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-006-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Great Mosque of Córdoba (Mezquita, 786 CE+) — double-arched hypostyle hall, red-white voussoirs, 856 columns", "type": "fact"}, {"text": "Alhambra, Granada (1238-1358) — Nasrid palace, Court of the Lions, muqarnas ceilings", "type": "fact"}, {"text": "Dome of the Rock, Jerusalem (691 CE) — octagonal plan, earliest surviving Islamic monument", "type": "fact"}, {"text": "Great Mosque of Damascus (Umayyad Mosque, 706 CE) — earliest monumental mosque", "type": "fact"}, {"text": "Taj Mahal, Agra (1632-53) — Mughal, white marble, mausoleum, Shah Jahan for Mumtaz Mahal", "type": "fact"}, {"text": "Blue Mosque (Sultan Ahmed), Istanbul — six minarets, cascading domes, Iznik tiles", "type": "fact"}, {"text": "Süleymaniye Mosque, Istanbul — Mimar Sinan, Ottoman classical period masterpiece", "type": "fact"}, {"text": "Selimiye Mosque, Edirne — Sinan''s masterwork, single 31.3m dome", "type": "fact"}, {"text": "Great Mosque of Djenné, Mali — largest mud-brick building in the world", "type": "fact"}, {"text": "Isfahan (Iran) — Safavid capital, Naqsh-e Jahan Square, Shah Mosque, tilework mastery", "type": "fact"}, {"text": "Samarkand — Registan Square, Timurid architecture, monumental madrasas", "type": "fact"}, {"text": "Maranao/Tausug Islamic architecture in Mindanao (Philippine connection)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-HIST-006-02';

